  insert into public.content_entries (collection, id, sort_order, visible, data) values
    ('profile', 'profile', 0, true, $json${"name":"Wandana Herath","headline":"Computer Science Undergraduate","supportingLine":"University of Jaffna, Sri Lanka","intro":"I’m a Computer Science undergraduate at the University of Jaffna. I enjoy building software around real workflows, from role-based dashboards to department automation.","institution":"University of Jaffna","location":"Sri Lanka","availability":"Open to software and IT internship opportunities","portrait":null,"cvUrl":null,"email":"wandanaherath.wdh@gmail.com","socials":[{"platform":"github","label":"GitHub","href":"https://github.com/Wandana-wdh","handle":"github.com/Wandana-wdh"},{"platform":"linkedin","label":"LinkedIn","href":"https://www.linkedin.com/in/wandana-herath-88a3ab264","handle":"linkedin.com/in/wandana-herath-88a3ab264"},{"platform":"medium","label":"Medium","href":"https://medium.com/@wandanaherath.wdh","handle":"medium.com/@wandanaherath.wdh"},{"platform":"email","label":"Email","href":"mailto:wandanaherath.wdh@gmail.com","handle":"wandanaherath.wdh@gmail.com"}],"focusAreas":["Full-Stack Development","React & Node.js","Role-Based Access","Cloud & Edge","Software Testing"],"about":{"intro":"I’m Wandana Herath, a Computer Science undergraduate at the University of Jaffna. I’m drawn to the practical side of building software: figuring out what different users need and turning that into an interface they can work with. On our Civil Engineering Management System team, I worked on role-based access and dashboards for engineering and administrative users. Outside coursework, I contributed to the IEEE Student Branch finance committee and started sharing what I’m learning through writing.","academicBackground":"Computer Science undergraduate at the University of Jaffna since 2023, building strong fundamentals in data structures and algorithms and backend development.","professionalInterests":["Full-stack web development","Backend development","Role-based dashboards and access control","Cloud and edge computing","Software testing and documentation","Cybersecurity fundamentals"],"careerAspirations":"To grow as a software engineer through real-world development work — starting with a software or IT internship where I can contribute to production code and keep learning by building."}}$json$::jsonb),
    ('projects', 'cems', 0, true, $json${"slug":"civil-engineering-management-system","title":"Civil Engineering Management System (CEMS)","shortTitle":"CEMS","summary":"A team-built management system with role-based access and dashboards for engineering and administrative users.","description":["CEMS is a team project: a management system that serves both engineering and administrative users, each with access to the views and tools relevant to their role."],"category":"Web Application","tech":["React","Protected Routes","Role-Based Access","Dashboards"],"highlights":["Separate dashboards for engineering and administrative users","Role-based access to protected areas of the application"],"contribution":["Implemented protected React routes for role-based access.","Updated the dashboards for engineering and administrative users."],"role":"Team member","team":true,"year":null,"cover":null,"gallery":[],"artwork":"grid","repositories":[],"liveUrl":null,"credentialIds":["cems-confirmation-letter"]}$json$::jsonb),
    ('projects', 'hospital-e-channeling', 1, true, $json${"slug":"hospital-e-channeling-system","title":"Hospital E-Channeling System","summary":"An e-channeling system for finding doctors and booking hospital appointments online.","description":[],"category":"Web Application","tech":[],"highlights":[],"contribution":[],"role":null,"team":false,"year":null,"cover":null,"gallery":[],"artwork":"pulse","repositories":[],"liveUrl":null,"credentialIds":[]}$json$::jsonb),
    ('projects', 'edge-azure-iot', 2, true, $json${"slug":"edge-azure-iot-department-automation","title":"Edge and Azure IoT Department Automation","summary":"A cloud–edge IoT design for a smart campus: simulated room sensors, an edge rule engine and Azure cloud reporting.","description":["Coursework on designing a smart campus solution with cloud–edge integration. The submission covers an architecture design, business continuity and disaster recovery (BCDR) techniques, a BANT analysis, and working Python code.","The code simulates temperature and occupancy sensors, runs an edge rule engine that raises alerts when a room exceeds 30 °C, uploads data to the cloud, and produces room occupancy and temperature reports."],"category":"IoT & Cloud","tech":["Python","Microsoft Azure","MQTT / HTTPS","Edge Computing"],"highlights":["Sensor simulation for temperature and occupancy","Edge rule engine with temperature alerts","Cloud upload and reporting","Architecture, BCDR and BANT analysis"],"contribution":[],"role":null,"team":false,"year":"2026","cover":null,"gallery":[],"artwork":"circuit","repositories":[{"label":"Source code","url":"https://github.com/Wandana-wdh/Edge-Assignment-2025"}],"liveUrl":null,"credentialIds":[]}$json$::jsonb),
    ('projects', 'personal-portfolio', 3, true, $json${"slug":"personal-portfolio-website","title":"Personal Portfolio Website","summary":"A responsive portfolio for my projects, education, certificates, and writing, with a private editor for updating content and publishing changes.","description":["This website is my personal portfolio. Visitors can browse my projects, education, certificates, volunteering, events and articles on responsive pages with light and dark themes. The frontend is built with React, TypeScript, Vite and Tailwind CSS.","Behind the public pages is a private editor that only my account can sign in to, using Supabase Auth. I sign in, edit an entry and save it as a draft, preview the whole site with my drafts, and publish when it is ready. Publishing updates the live site without changing code or redeploying.","From the editor I can upload certificates as PDFs or images, and project photos with captions and alt text. Uploads stay private in Supabase Storage until I publish. Content is stored in a PostgreSQL database on Supabase, with Row Level Security so that only the owner account can change it.","I connected the GitHub repository to Vercel, so changes pushed to GitHub are built and deployed automatically, and configured the Vercel project with the Supabase project URL and publishable key so the site loads its published content from Supabase."],"category":"Web Application","tech":["React","TypeScript","Vite","Tailwind CSS","Supabase","PostgreSQL","GitHub","Vercel"],"highlights":["Responsive pages with light and dark themes","Owner-only sign-in with Supabase Auth","Save, preview and publish workflow","Certificate and photo uploads with Supabase Storage","Row Level Security on the database and file storage","Content updates without redeploying"],"contribution":["Connected the GitHub repository to Vercel for automatic deployments.","Set up the Supabase project: ran the database migrations, created the owner account and turned off public sign-up.","Configured the site’s Supabase settings in Vercel, and keep the content up to date through the private editor."],"role":null,"team":false,"year":"2026","cover":{"src":"/images/projects/personal-portfolio/cover.webp","alt":"Homepage of the portfolio website in dark mode, showing the hero introduction and a featured project card","width":1600,"height":900},"gallery":[{"src":"/images/projects/personal-portfolio/projects-page.webp","alt":"Projects page in light mode with three equal-size project cards and category filters","width":1600,"height":900,"caption":"Projects page in light mode"},{"src":"/images/projects/personal-portfolio/education-mobile.webp","alt":"The Education section on a phone, showing university and school entries on a vertical timeline","width":1600,"height":900,"caption":"Education section on a phone"},{"src":"/images/projects/personal-portfolio/admin-project-editor.webp","alt":"The private editor in dark mode, editing a project’s title, page URL, category and year","width":1600,"height":900,"caption":"Editing a project in the private editor"},{"src":"/images/projects/personal-portfolio/admin-certificate-upload.webp","alt":"The New certificate dialog with title, issuer, type, issue date, a PDF or image upload and the List on the Achievements page switch","width":1600,"height":900,"caption":"Adding a certificate with its file"},{"src":"/images/projects/personal-portfolio/admin-publish.webp","alt":"The Publish changes dialog explaining that saved drafts will replace the public site","width":1600,"height":900,"caption":"Publishing saved drafts"}],"artwork":"lattice","repositories":[],"liveUrl":"https://wandana.vercel.app","credentialIds":[]}$json$::jsonb),
