-- Generated by scripts/generate-import.ts from src/data — do not edit by hand.
-- Initial import for a NEW project: imports the portfolio content as drafts and
-- publishes it as the first version.
-- Safe to run again: if the site already has content or a published version it
-- does nothing, so it can never overwrite (or bring back) edits made in /admin.

do $import$
begin
  if exists (select 1 from public.content_entries) or exists (select 1 from public.site_versions) then
    raise notice 'The site already has content, so the initial import was skipped.';
    return;
  end if;

  on conflict (collection, id) do nothing;

  select public.build_snapshot(), '{}'
  where not exists (select 1 from public.site_versions);
end;
$import$;
